pub fn for_icon(ic: Icon) ?[]const Cmd {
    return switch (ic) {
        .close => &x,
        .close_circle => &@"circle-x",
        .check => &check,
        .check_circle => &@"circle-check",
        .plus => &plus,
        .plus_square => &@"square-plus",
