        .warning => &@"triangle-alert",
        .bold => &bold,
        .italic => &italic,
        .underline => &underline,
        .align_left => &@"text-align-start",
        .align_center => &@"text-align-center",
        .align_right => &@"text-align-end",
        .share => &share,
        .save => &save,
        .copy => &copy,
        .grid => &@"grid-3x3",
        .layout_grid => &@"layout-grid",
        .bell => &bell,
        .bell_badge => &@"bell-dot",
