        .eye_slash => &@"eye-off",
        .calendar => &calendar,
        .folder => &folder,
        .lock => &@"lock",
        .layers => &@"layers",
        .square_terminal => &@"square-terminal",
        .folder_dot => &@"folder-dot",
        .folder_open_dot => &@"folder-open-dot",
        .folder_open => &@"folder-open",
        .trash => &@"trash-2",
        .doc => &@"file-text",
        .envelope => &mail,
        .message => &@"message-square",
        .person => &user,
        .people => &users,
